<?php
if ( ! defined( 'ABSPATH' ) ) { exit; }

class RUSPIC_Cat_Shortcodes {
    private $db;
    public function __construct( $db ) { $this->db=$db; add_action('wp_enqueue_scripts',array($this,'assets')); add_shortcode('ruspic_catalog',array($this,'catalog')); add_shortcode('ruspic_product',array($this,'product')); add_shortcode('ruspic_brands',array($this,'brands')); }
    public function assets() { wp_enqueue_style('ruspic-cat-front',RUSPIC_CAT_URL.'assets/css/frontend.css',array(),RUSPIC_CAT_VERSION); wp_enqueue_script('ruspic-cat-front',RUSPIC_CAT_URL.'assets/js/frontend.js',array(),RUSPIC_CAT_VERSION,true); wp_localize_script('ruspic-cat-front','RUSPIC_CAT',array('api'=>esc_url_raw(rest_url('ruspic/v1/')),'nonce'=>wp_create_nonce('wp_rest'))); }
    private function money($price,$currency='RUB'){ if($price===null||$price==='')return 'Цена по запросу'; $symbols=array('RUB'=>'₽','USD'=>'$','EUR'=>'€'); return number_format((float)$price,2,',',' ').' '.($symbols[$currency]??$currency); }
    private function stock_label($p){ if(isset($p->stock_status)&&$p->stock_status==='out_of_stock')return 'Нет в наличии'; if(isset($p->stock_qty)&&$p->stock_qty!==null&&(float)$p->stock_qty>0)return 'В наличии · '.number_format((float)$p->stock_qty,0,',',' ').' шт.'; return 'В наличии'; }
    private function image_url($attachment_id,$size='large'){ return $attachment_id?wp_get_attachment_image_url((int)$attachment_id,$size):''; }
    private function card($p){ $image=$this->image_url($p->image_id??0,'medium'); $href=add_query_arg('ruspic_product',(int)$p->id); ob_start(); ?><article class="ruspic-product-card"><a class="ruspic-product-card__media" href="<?php echo esc_url($href); ?>" aria-label="<?php echo esc_attr($p->name); ?>"><?php if($image): ?><img src="<?php echo esc_url($image); ?>" alt="<?php echo esc_attr($p->name); ?>" loading="lazy"><?php else: ?><span class="ruspic-product-card__placeholder">RUSPIC</span><?php endif; ?></a><div class="ruspic-product-card__body"><div class="ruspic-product-card__meta"><?php echo esc_html($p->brand_name?:'RUSPIC'); ?></div><h3><a href="<?php echo esc_url($href); ?>"><?php echo esc_html($p->name); ?></a></h3><?php if($p->sku): ?><div class="ruspic-sku">Арт. <?php echo esc_html($p->sku); ?></div><?php endif; ?><div class="ruspic-stock"><span></span><?php echo esc_html($this->stock_label($p)); ?></div><p><?php echo esc_html(wp_trim_words(wp_strip_all_tags($p->short_description),18)); ?></p><div class="ruspic-product-card__bottom"><strong><?php echo esc_html($this->money($p->price,$p->currency)); ?></strong><button type="button" data-ruspic-add data-id="<?php echo (int)$p->id; ?>" data-name="<?php echo esc_attr($p->name); ?>">В корзину</button></div></div></article><?php return ob_get_clean(); }
    public function catalog($atts=array()){ $atts=shortcode_atts(array('limit'=>24),$atts); $products=$this->db->get_products(array('limit'=>(int)$atts['limit'],'offset'=>0)); $brands=$this->db->get_brands(array('limit'=>100)); $cats=$this->db->get_all_categories(); ob_start(); ?><section class="ruspic-catalog" data-ruspic-catalog><div class="ruspic-catalog__toolbar"><label class="ruspic-search"><span class="screen-reader-text">Поиск</span><input data-ruspic-search type="search" placeholder="Поиск по названию или артикулу..." autocomplete="off"></label><select data-ruspic-brand aria-label="Бренд"><option value="0">Все бренды</option><?php foreach($brands as $b): ?><option value="<?php echo (int)$b->id; ?>"><?php echo esc_html($b->name); ?></option><?php endforeach; ?></select><select data-ruspic-category aria-label="Категория"><option value="0">Все категории</option><?php foreach($cats as $c): ?><option value="<?php echo (int)$c->id; ?>"><?php echo esc_html($c->name); ?></option><?php endforeach; ?></select></div><div class="ruspic-product-grid" data-ruspic-products><?php foreach($products as $p)echo $this->card($p); ?><?php if(!$products): ?><div class="ruspic-empty">Товары не найдены.</div><?php endif; ?></div></section><?php return ob_get_clean(); }
    public function product($atts=array()){ $id=(int)($_GET['ruspic_product']??($atts['id']??0)); if(!$id)return '<p class="ruspic-empty">Не указан товар.</p>'; $p=$this->db->get_product($id); if(!$p)return '<p class="ruspic-empty">Товар не найден.</p>'; $gallery=array(); if(!empty($p->image_id))$gallery[]=(int)$p->image_id; foreach((array)($p->images??array()) as $img){if(!empty($img->attachment_id))$gallery[]=(int)$img->attachment_id;} $gallery=array_values(array_unique($gallery)); $main=$gallery?$this->image_url($gallery[0],'large'):''; ob_start(); ?><article class="ruspic-product"><div class="ruspic-breadcrumbs"><a href="<?php echo esc_url(remove_query_arg('ruspic_product')); ?>">Каталог</a><span>›</span><?php echo esc_html($p->category_name?:'Товары'); ?><span>›</span><?php echo esc_html($p->name); ?></div><div class="ruspic-product__top"><div class="ruspic-product__gallery"><div class="ruspic-product__main-image"><?php if($main): ?><img src="<?php echo esc_url($main); ?>" alt="<?php echo esc_attr($p->name); ?>" data-ruspic-main-image><?php else: ?><span class="ruspic-product-card__placeholder">RUSPIC</span><?php endif; ?></div><?php if(count($gallery)>1): ?><div class="ruspic-product__thumbs"><?php foreach($gallery as $i=>$attachment_id): $thumb=$this->image_url($attachment_id,'thumbnail'); $large=$this->image_url($attachment_id,'large'); if(!$thumb)continue; ?><button type="button" class="<?php echo $i===0?'is-active':''; ?>" data-ruspic-thumb data-large="<?php echo esc_url($large); ?>"><img src="<?php echo esc_url($thumb); ?>" alt=""></button><?php endforeach; ?></div><?php endif; ?></div><div class="ruspic-product__info"><div class="ruspic-product__meta"><?php echo esc_html($p->brand_name?:'RUSPIC'); ?></div><h1><?php echo esc_html($p->name); ?></h1><div class="ruspic-product__codes"><?php if($p->sku): ?><span>Артикул: <b><?php echo esc_html($p->sku); ?></b></span><?php endif; ?><?php if($p->brand_name): ?><span>Производитель: <b><?php echo esc_html($p->brand_name); ?></b></span><?php endif; ?></div><div class="ruspic-product__actions"><button type="button" data-ruspic-favorite>♡ В избранное</button><button type="button" data-ruspic-compare>⇄ Сравнить</button></div><div class="ruspic-buybox"><div class="ruspic-buybox__prices"><div><span>Цена</span><strong><?php echo esc_html($this->money($p->price,$p->currency)); ?><small>/шт</small></strong></div><div><span>Оптовая цена</span><strong class="ruspic-price-muted">По запросу</strong></div></div><div class="ruspic-stock ruspic-stock--large"><span></span><?php echo esc_html($this->stock_label($p)); ?></div><div class="ruspic-buybox__row"><div class="ruspic-qty" data-ruspic-qty><button type="button" data-qty-minus aria-label="Уменьшить">−</button><input value="1" min="1" type="number" inputmode="numeric" aria-label="Количество"><button type="button" data-qty-plus aria-label="Увеличить">+</button></div><button class="ruspic-main-button" type="button" data-ruspic-add data-id="<?php echo (int)$p->id; ?>" data-name="<?php echo esc_attr($p->name); ?>">В корзину</button></div><div class="ruspic-buybox__note">Цена указана с учётом текущего прайса. Для оптового предложения свяжитесь с менеджером.</div></div></div></div><div class="ruspic-product__tabs" role="tablist"><a href="#ruspic-specs">Описание и характеристики</a><a href="#ruspic-questions">Вопросы</a><a href="#ruspic-video">Видеоматериалы</a></div><div class="ruspic-product__content"><section id="ruspic-specs" class="ruspic-product__description"><h2>Описание</h2><div class="ruspic-richtext"><?php echo wp_kses_post(wpautop($p->description)); ?></div></section><?php if($p->attributes): ?><section class="ruspic-specs-wrap"><h2>Характеристики</h2><table class="ruspic-specs"><tbody><?php foreach($p->attributes as $a): ?><tr><th><?php echo esc_html($a->name); ?></th><td><?php echo esc_html($a->value_text); ?><?php if($a->unit)echo ' '.esc_html($a->unit); ?></td></tr><?php endforeach; ?></tbody></table></section><?php endif; ?><section id="ruspic-questions" class="ruspic-info-panel"><h2>Вопросы</h2><p>Нужна консультация по совместимости, поставке или оптовой цене? Оставьте заявку через корзину — менеджер RUSPIC свяжется с вами.</p></section><section id="ruspic-video" class="ruspic-info-panel"><h2>Видеоматериалы</h2><p>Видеоматериалы для этого товара появятся здесь после добавления ссылки в карточку.</p></section></div></article><?php return ob_get_clean(); }
    public function brands(){ $brands=$this->db->get_brands(array('limit'=>100)); ob_start(); ?><div class="ruspic-brands"><?php foreach($brands as $b): ?><div class="ruspic-brand"><strong><?php echo esc_html($b->name); ?></strong><?php if($b->website_url): ?><a href="<?php echo esc_url($b->website_url); ?>" target="_blank" rel="noopener">Сайт производителя</a><?php endif; ?></div><?php endforeach; ?></div><?php return ob_get_clean(); }
}
